window.docContents[73].resolve({"/Elementary-Functions/___4___10-Integrals/#chapter-4-section-10":{"contents":"Source: NIST Digital Library of Mathematical Functions, §4.10.\n\nThis section collects antiderivatives and definite integrals for logarithms and\nexponentials. Complex antiderivatives use the principal logarithm on an explicit\nbranch domain; definite integrals use the indicated real intervals and measures.\n\n\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions","header":"4.10. §4.10 Integrals","id":"/Elementary-Functions/___4___10-Integrals/#chapter-4-section-10"}});